// Record: PublicStep.
impl Record for PublicStep {
    type Limits = Limits;
    const TAIL: Path = paths::PUBLIC_STEP_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 19)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 19)?.decoded)
    }

    fn write(&self, _limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Producing => field::put(out, &[0], paths::PUBLIC_STEP_TAG),
            Self::Opening => field::put(out, &[1], paths::PUBLIC_STEP_TAG),
            Self::Recreating => field::put(out, &[2], paths::PUBLIC_STEP_TAG),
            Self::Reopening => field::put(out, &[3], paths::PUBLIC_STEP_TAG),
            Self::Checking => field::put(out, &[4], paths::PUBLIC_STEP_TAG),
            Self::Gating => field::put(out, &[5], paths::PUBLIC_STEP_TAG),
            Self::Queued => field::put(out, &[6], paths::PUBLIC_STEP_TAG),
            Self::First => field::put(out, &[7], paths::PUBLIC_STEP_TAG),
            Self::Updating => field::put(out, &[8], paths::PUBLIC_STEP_TAG),
            Self::Resolving => field::put(out, &[9], paths::PUBLIC_STEP_TAG),
            Self::Repairing => field::put(out, &[10], paths::PUBLIC_STEP_TAG),
            Self::Landing => field::put(out, &[11], paths::PUBLIC_STEP_TAG),
            Self::Landed => field::put(out, &[12], paths::PUBLIC_STEP_TAG),
            Self::Ended => field::put(out, &[13], paths::PUBLIC_STEP_TAG),
            Self::Ready => field::put(out, &[14], paths::PUBLIC_STEP_TAG),
            Self::Preparing => field::put(out, &[15], paths::PUBLIC_STEP_TAG),
            Self::Verifying => field::put(out, &[16], paths::PUBLIC_STEP_TAG),
            Self::Red => field::put(out, &[17], paths::PUBLIC_STEP_TAG),
            Self::Cleared => field::put(out, &[18], paths::PUBLIC_STEP_TAG),
        }
    }

    fn read(_limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::PUBLIC_STEP_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Producing),
            1 => Ok(Self::Opening),
            2 => Ok(Self::Recreating),
            3 => Ok(Self::Reopening),
            4 => Ok(Self::Checking),
            5 => Ok(Self::Gating),
            6 => Ok(Self::Queued),
            7 => Ok(Self::First),
            8 => Ok(Self::Updating),
            9 => Ok(Self::Resolving),
            10 => Ok(Self::Repairing),
            11 => Ok(Self::Landing),
            12 => Ok(Self::Landed),
            13 => Ok(Self::Ended),
            14 => Ok(Self::Ready),
            15 => Ok(Self::Preparing),
            16 => Ok(Self::Verifying),
            17 => Ok(Self::Red),
            18 => Ok(Self::Cleared),
            19..=u8::MAX => Err(Problem { path: paths::PUBLIC_STEP_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

